package br.com.oficina.domain;
import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity public class OrdemServico { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) private Cliente cliente; @ManyToOne(optional=false) private Veiculo veiculo; @Enumerated(EnumType.STRING) @Column(nullable=false) private StatusOs status=StatusOs.RECEBIDA; @Column(nullable=false,precision=12,scale=2) private BigDecimal total=BigDecimal.ZERO; private Instant criadaEm=Instant.now(); private Instant iniciadaEm; private Instant finalizadaEm; @ElementCollection private List<UUID> servicos=new ArrayList<>(); @ElementCollection private Map<UUID,Integer> pecas=new HashMap<>();
 protected OrdemServico(){} public OrdemServico(Cliente c,Veiculo v){cliente=c;veiculo=v;} public UUID getId(){return id;} public Cliente getCliente(){return cliente;} public Veiculo getVeiculo(){return veiculo;} public StatusOs getStatus(){return status;} public BigDecimal getTotal(){return total;} public Instant getCriadaEm(){return criadaEm;} public Instant getIniciadaEm(){return iniciadaEm;} public Instant getFinalizadaEm(){return finalizadaEm;} public List<UUID> getServicos(){return List.copyOf(servicos);} public Map<UUID,Integer> getPecas(){return Map.copyOf(pecas);} public void adicionarServico(Servico s){servicos.add(s.getId());total=total.add(s.getPreco());} public void adicionarPeca(Peca p,int qtd){pecas.merge(p.getId(),qtd,Integer::sum);total=total.add(p.getPrecoUnitario().multiply(BigDecimal.valueOf(qtd)));} public void mudarStatus(StatusOs novo){ if(!transicaoPermitida(novo))throw new IllegalStateException("Transição de status inválida: "+status+" para "+novo); status=novo; if(novo==StatusOs.EM_EXECUCAO)iniciadaEm=Instant.now(); if(novo==StatusOs.FINALIZADA)finalizadaEm=Instant.now();} private boolean transicaoPermitida(StatusOs novo){return switch(status){case RECEBIDA->novo==StatusOs.EM_DIAGNOSTICO;case EM_DIAGNOSTICO->novo==StatusOs.AGUARDANDO_APROVACAO;case AGUARDANDO_APROVACAO->novo==StatusOs.EM_EXECUCAO||novo==StatusOs.ORCAMENTO_RECUSADO;case EM_EXECUCAO->novo==StatusOs.FINALIZADA;case FINALIZADA->novo==StatusOs.ENTREGUE;case ENTREGUE,ORCAMENTO_RECUSADO->false;};} }
